namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class MemoryFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.Memory> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.Memory>(resourceName)
{

    internal List<InnerMemoryIndexedKeyFactory> IndexedKeysFactories { get; set; } = [];

    internal List<InnerMemoryNamespaceKeyEntryFactory> NamespaceKeysFactories { get; set; } = [];

    internal List<InnerMemoryMemoryStrategyFactory> MemoryStrategiesFactories { get; set; } = [];

    internal InnerMemoryStreamDeliveryResourcesFactory StreamDeliveryResourcesFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.Memory Create()
    {
        var memoryResult = CreateMemory();
        factoryAction?.Invoke(memoryResult);

        return memoryResult;
    }

    private Humidifier.BedrockAgentCore.Memory CreateMemory()
    {
        var memoryResult = new Humidifier.BedrockAgentCore.Memory
        {
            GivenName = InputResourceName,
        };

        return memoryResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.Memory result)
    {
        base.CreateChildren(result);

        result.IndexedKeys = IndexedKeysFactories.Any() ? IndexedKeysFactories.Select(x => x.Build()).ToList() : null;
        result.NamespaceKeys = NamespaceKeysFactories.Any() ? NamespaceKeysFactories.Select(x => x.Build()).ToList() : null;
        result.MemoryStrategies = MemoryStrategiesFactories.Any() ? MemoryStrategiesFactories.Select(x => x.Build()).ToList() : null;
        result.StreamDeliveryResources ??= StreamDeliveryResourcesFactory?.Build();
    }

} // End Of Class

